Here’s a simple JavaScript todo list app that saves tasks in `localStorage`, so they remain after refreshing the page.

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Todo List</title>
  <style>
    body {
      font-family: system-ui, sans-serif;
      max-width: 500px;
      margin: 40px auto;
      padding: 0 16px;
    }

    form { display: flex; gap: 8px; }
    input { flex: 1; padding: 10px; }
    button { padding: 10px 14px; cursor: pointer; }

    ul { padding: 0; list-style: none; }
    li {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      padding: 10px 0;
      border-bottom: 1px solid #ddd;
    }

    .done span {
      text-decoration: line-through;
      color: #777;
    }
  </style>
</head>
<body>
  <h1>My Todos</h1>

  <form id="todo-form">
    <input id="todo-input" placeholder="Add a task…" required />
    <button>Add</button>
  </form>

  <ul id="todo-list"></ul>

  <script>
    const form = document.querySelector("#todo-form");
    const input = document.querySelector("#todo-input");
    const list = document.querySelector("#todo-list");

    let todos = JSON.parse(localStorage.getItem("todos") || "[]");

    function saveTodos() {
      localStorage.setItem("todos", JSON.stringify(todos));
    }

    function renderTodos() {
      list.innerHTML = "";

      todos.forEach((todo, index) => {
        const item = document.createElement("li");
        item.className = todo.done ? "done" : "";

        item.innerHTML = `
          <label>
            <input type="checkbox" ${todo.done ? "checked" : ""}>
            <span>${todo.text}</span>
          </label>
          <button aria-label="Delete task">Delete</button>
        `;

        item.querySelector('input[type="checkbox"]').addEventListener("change", () => {
          todos[index].done = !todos[index].done;
          saveTodos();
          renderTodos();
        });

        item.querySelector("button").addEventListener("click", () => {
          todos.splice(index, 1);
          saveTodos();
          renderTodos();
        });

        list.appendChild(item);
      });
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const text = input.value.trim();
      if (!text) return;

      todos.push({ text, done: false });
      saveTodos();
      renderTodos();

      input.value = "";
      input.focus();
    });

    renderTodos();
  </script>
</body>
</html>
```

Save it as `index.html` and open it in a browser. It supports adding, completing, deleting, and persisting tasks. `localStorage` stores string key/value data per browser origin, so this is suitable for lightweight local-only data—not accounts or sensitive information.

